package com.example.Email.Entity;
import com.example.CRM.Entity.User;import jakarta.persistence.*;import lombok.*;import java.time.Instant;
@Entity @Table(name="email_crm_links",uniqueConstraints=@UniqueConstraint(name="uq_email_crm_link",columnNames={"message_id","entity_type","entity_id","relationship_type"})) @Getter @Setter @NoArgsConstructor
public class EmailCrmLink { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="link_id") private Long linkId; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="message_id") private EmailMessage message; @Column(name="entity_type",length=30,nullable=false) private String entityType; @Column(name="entity_id",length=64,nullable=false) private String entityId; @Column(name="relationship_type",length=30,nullable=false) private String relationshipType="RELATED"; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="linked_by_user_id") private User linkedBy; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); }
